-- Hibás bolti URL-ek javítása (Gunfire: „https://gunfire.comhttps//gunfire.com/en/...” → „https://gunfire.com/en/...”).
-- Futtatás: GitHub → Actions → d1-sql → fájl: d1/javitas_urlek_2026-11-09.sql. Újrafuttatható.
-- Csak ott módosít, ahol a domain-részben (az első „/” előtt) egy második „http(s)://” vagy „http(s)//” kezdődik.
UPDATE offers SET url = CASE
    WHEN substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'https//%' THEN 'https://' || substr(substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')), 8)
    WHEN substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'http//%' THEN 'http://' || substr(substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')), 7)
    ELSE substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) END
WHERE instr(substr(url, instr(url, '://') + 3), 'http') > 0 AND instr(substr(url, instr(url, '://') + 3), 'http') < instr(substr(url, instr(url, '://') + 3) || '/', '/') AND (substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'https://%' OR substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'http://%' OR substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'https//%' OR substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'http//%');

SELECT count(*) AS meg_hibas, (SELECT count(*) FROM offers WHERE url LIKE 'https://gunfire.com/%') AS gunfire_jo FROM offers WHERE instr(substr(url, instr(url, '://') + 3), 'http') > 0 AND instr(substr(url, instr(url, '://') + 3), 'http') < instr(substr(url, instr(url, '://') + 3) || '/', '/') AND (substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'https://%' OR substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'http://%' OR substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'https//%' OR substr(substr(url, instr(url, '://') + 3), instr(substr(url, instr(url, '://') + 3), 'http')) LIKE 'http//%');
